from fastapi.responses import HTMLResponse


def mission_environment_page() -> HTMLResponse:
    return HTMLResponse(r'''<!doctype html>
<html class="nct-shell-loading" lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>NCT · Mission Environment</title><style id="nct-shell-bootstrap">html.nct-shell-loading body{visibility:hidden}</style>
<style>:root{color-scheme:dark;--bg:#09131c;--panel:#112330;--line:#304955;--text:#e8f2f6;--muted:#abc0cb;--accent:#62d9ba;--warn:#f4c66b;--bad:#ff9b9b}*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 system-ui}header{padding:20px 4vw;border-bottom:1px solid var(--line)}main{max-width:1420px;margin:auto;padding:30px 24px}.panel{margin:0 0 18px;padding:22px;border:1px solid var(--line);border-radius:12px;background:var(--panel)}h1{margin:0;font-size:30px}h2{margin:0 0 10px;font-size:20px}h3{margin:0}.muted,p{color:var(--muted)}.notice{padding:12px 14px;border-left:4px solid var(--warn);background:#f4c66b12;color:var(--text)}.tool-grid{display:grid;grid-template-columns:repeat(4,minmax(210px,1fr));gap:12px}.tool{display:grid;gap:7px;padding:14px;border:1px solid var(--line);border-radius:9px;background:#0b1b26}.badge{display:inline-block;width:max-content;padding:2px 9px;border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:12px}.badge.available,.authorized{border-color:#35bc91;color:#7ff0ca}.badge.prohibited,.bad{border-color:#b85b63;color:#ffacb2}.badge.unknown,.warn{border-color:#a9883b;color:#f4d37e}button,input,select,textarea{font:inherit;border:1px solid var(--line);border-radius:7px;background:#0b1b26;color:var(--text);padding:9px 11px}button{cursor:pointer;font-weight:750;background:#193445}button.primary{background:var(--accent);color:#09251d}button:disabled{opacity:.5;cursor:not-allowed}.table-wrap{overflow:auto;max-width:100%;border:1px solid var(--line);border-radius:9px}table{width:100%;min-width:1040px;border-collapse:collapse}th,td{padding:11px 12px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{position:sticky;top:0;z-index:1;background:#172d3a;color:var(--text);font-size:12px}td small{display:block;color:var(--muted)}.actions{display:flex;flex-wrap:wrap;gap:9px;align-items:center}.pager{justify-content:space-between;margin-top:12px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}label{display:grid;gap:5px;font-weight:700}textarea{min-height:90px;resize:vertical}.checks{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.checks label{display:flex;align-items:flex-start;gap:7px;font-weight:500}.checks input{margin-top:4px}.editor{margin-top:18px;border-top:1px solid var(--line);padding-top:18px}.history{max-height:260px;overflow:auto;padding-left:20px}.history li{margin:8px 0}.status{min-height:24px}.scope-name{font-weight:800}.readonly{padding:9px 12px;border:1px solid var(--line);border-radius:7px;background:#ffffff08}.derived{color:var(--warn)}body.nct-guide-open .tool-grid{grid-template-columns:repeat(2,minmax(220px,1fr))}@media(max-width:1050px){.tool-grid{grid-template-columns:repeat(2,minmax(220px,1fr))}}@media(max-width:700px){main{padding:20px 12px}.tool-grid,body.nct-guide-open .tool-grid,.grid,.checks{grid-template-columns:1fr}}</style>
<script src="/assets/nct-session.js"></script></head><body><header><strong>NCT</strong> · Network Correlation &amp; Triage</header><main>
<p>Settings / Mission Environment</p><h1>Mission environment</h1>
<p>Record which evidence tools exist, what they cover, and where analysts must account for blind spots.</p>
<div class="notice"><strong>Exact-scope collection gate active.</strong> “Authorized” is an administrator-recorded description, not permission granted by NCT. “Prohibited” blocks Nmap collection when an analyst selects a Saved Network in that exact reviewed scope. Manual and unassociated targets remain Unknown and do not inherit permission from an address match. Existing operator authorization and No-Strike controls remain authoritative.</div>
<section class="panel" id="toolPanel"><h2>Available tools and access</h2><p>Availability says whether the tool can be used in this environment. It never means an active scan is authorized. Describe the access path without entering passwords, tokens, or keys.</p><div id="tools" class="tool-grid"><p>Loading…</p></div>
<div id="toolEditor" class="editor" hidden><h3 id="toolTitle">Edit tool</h3><form id="toolForm"><input id="toolKey" type="hidden"><input id="toolVersion" type="hidden"><div class="grid">
<label>Availability<select id="availability"><option value="unknown">Unknown / unconfigured</option><option value="available">Available</option><option value="unavailable">Unavailable</option></select></label>
<label>Installed or supported version<input id="versionText" maxlength="120" placeholder="Example: 4.6.0"></label>
<label>Access method<input id="accessMethod" maxlength="500" placeholder="Example: analyst workstation web interface"></label>
<label>Reason for change<input id="toolReason" maxlength="500" required placeholder="Why is this declaration correct?"></label></div>
<label>Notes<textarea id="toolNotes" maxlength="1000" placeholder="Roles, request process, or operational limits. Do not enter credentials."></textarea></label>
<div class="actions"><button class="primary" id="saveTool" type="submit">Save tool declaration</button><button id="cancelTool" type="button">Close</button></div></form><ol id="toolHistory" class="history"></ol></div></section>
<section class="panel" id="coveragePanel"><h2>Coverage by Network Scope</h2><p>Every row begins as Unknown until an administrator records the reviewed environment. The active-scan-prohibited blind spot follows the Nmap authorization value automatically.</p>
<div class="table-wrap"><table><thead><tr><th>Network Scope</th><th>Nmap evidence</th><th>Nmap authorization</th><th>Arkime</th><th>Kibana</th><th>Configuration</th><th>Blind spots</th><th>Action</th></tr></thead><tbody id="scopeRows"><tr><td colspan="8">Loading…</td></tr></tbody></table></div>
<div class="actions pager"><span id="pageSummary" class="muted"></span><span class="actions"><button id="previous">Previous</button><button id="next">Next</button></span></div>
<div id="scopeEditor" class="editor" hidden><h3 id="scopeTitle">Edit scope coverage</h3><p class="muted">This records reviewed conditions and does not assign evidence or start a scan. Prohibited blocks later Nmap collection only after an analyst selects a Saved Network in this exact scope and the server rechecks this declaration.</p><form id="scopeForm"><input id="scopeId" type="hidden"><input id="scopeVersion" type="hidden"><div class="grid">
<label>Nmap evidence coverage<select id="nmapCoverage"></select></label><label>Nmap authorization<select id="nmapAuthorization"><option value="unknown">Unknown</option><option value="authorized">Authorized (recorded description)</option><option value="prohibited">Prohibited (blocks exact reviewed scope)</option></select></label>
<label>Arkime coverage<select id="arkimeCoverage"></select></label><label>Kibana / Elastic coverage<select id="kibanaCoverage"></select></label>
<label>Configuration coverage<select id="configCoverage"></select></label><label>Device evidence detail<select id="deviceEvidence"><option value="unknown">Unknown</option><option value="full_configuration">Full configuration</option><option value="partial_configuration">Partial configuration</option><option value="command_output_only">Command output only</option><option value="analyst_known_manual">Analyst-known / manual</option><option value="unavailable">Unavailable</option></select></label></div>
<fieldset><legend>Known blind spots</legend><div id="blindSpots" class="checks"></div><p id="prohibitedNote" class="derived" hidden>Active scan prohibited will be shown automatically from the Nmap authorization selection.</p></fieldset>
<label>Notes<textarea id="scopeNotes" maxlength="1000" placeholder="Describe boundaries, gaps, or how this was verified. Do not enter credentials."></textarea></label>
<label>Reason for change<input id="scopeReason" maxlength="500" required placeholder="Why is this coverage declaration correct?"></label>
<div class="actions"><button class="primary" id="saveScope" type="submit">Save scope coverage</button><button id="cancelScope" type="button">Close</button></div></form><ol id="scopeHistory" class="history"></ol></div></section>
<p id="status" class="status" role="status" aria-live="polite"></p><a href="/settings/network-scopes">Manage Network Scopes</a> · <a href="/help/how-nct-works">How NCT Works</a></main>
<script>(()=>{
const $=id=>document.getElementById(id);const coverage=[['unknown','Unknown'],['available','Available'],['partial','Partial'],['unavailable','Unavailable']];
const flags=[['no_passive_coverage','No passive coverage'],['missing_configuration','Missing configuration'],['unknown_nat','Unknown NAT'],['partial_route_knowledge','Partial route knowledge'],['telemetry_gap','Telemetry gap'],['stale_evidence','Stale evidence'],['unsupported_parser_field_mapping','Unsupported parser or field mapping']];
let state={tools:[],scopes:[],scope_total:0,can_edit:false},offset=0,limit=25;
function options(select){select.replaceChildren(...coverage.map(([value,label])=>{const option=document.createElement('option');option.value=value;option.textContent=label;return option}))}
for(const id of ['nmapCoverage','arkimeCoverage','kibanaCoverage','configCoverage'])options($(id));
for(const [value,label] of flags){const wrap=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.value=value;wrap.append(input,document.createTextNode(label));$('blindSpots').append(wrap)}
async function api(url,options={}){const response=await fetch(url,{credentials:'same-origin',...options});let data={};try{data=await response.json()}catch(_){}if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:'Request failed');return data}
function setStatus(message,bad=false){$('status').textContent=message;$('status').className='status '+(bad?'bad':'')}
function label(value){return String(value||'unknown').replaceAll('_',' ')}
function badge(value){const span=document.createElement('span');span.className='badge '+value;span.textContent=label(value);return span}
function renderTools(){const root=$('tools');root.replaceChildren();for(const item of state.tools){const card=document.createElement('article'),title=document.createElement('h3'),version=document.createElement('div'),access=document.createElement('div'),button=document.createElement('button');card.className='tool';title.textContent=item.label;version.textContent=item.version_text?`Version: ${item.version_text}`:'Version not recorded';version.className='muted';access.textContent=item.access_method||'Access method not recorded';access.className='muted';button.textContent=state.can_edit?'Review or edit':'View history';button.dataset.missionTool=item.tool_key;button.onclick=()=>openTool(item);card.append(title,badge(item.availability),version,access,button);root.append(card)}}
function renderScopes(){const body=$('scopeRows');body.replaceChildren();if(!state.scopes.length){const row=document.createElement('tr'),cell=document.createElement('td');cell.colSpan=8;cell.textContent='No active Network Scopes are registered.';row.append(cell);body.append(row)}for(const item of state.scopes){const row=document.createElement('tr');const scope=document.createElement('td');scope.innerHTML=`<span class="scope-name"></span><small></small>`;scope.querySelector('span').textContent=item.scope_label;scope.querySelector('small').textContent=item.configured?`Reviewed version ${item.version}`:'Unconfigured';row.append(scope);for(const value of [item.nmap_coverage,item.nmap_authorization,item.arkime_coverage,item.kibana_coverage,item.config_coverage]){const cell=document.createElement('td');cell.append(badge(value));row.append(cell)}const blind=document.createElement('td');blind.textContent=item.blind_spots.length?item.blind_spots.map(label).join(', '):'None recorded';row.append(blind);const action=document.createElement('td'),button=document.createElement('button');button.textContent=state.can_edit?'Review or edit':'View history';button.dataset.missionScope=item.scope_id;button.onclick=()=>openScope(item);action.append(button);row.append(action);body.append(row)}$('pageSummary').textContent=state.scope_total?`${offset+1}–${Math.min(offset+limit,state.scope_total)} of ${state.scope_total}`:'0 scopes';$('previous').disabled=offset===0;$('next').disabled=offset+limit>=state.scope_total}
async function history(kind,key,root){const data=await api(`/api/mission-environment/${kind}/${encodeURIComponent(key)}/history?limit=50`);root.replaceChildren();if(!data.items.length){const li=document.createElement('li');li.textContent='No saved changes yet.';root.append(li);return}for(const item of data.items){const li=document.createElement('li'),strong=document.createElement('strong'),detail=document.createElement('div');strong.textContent=`Version ${item.new_version}`;detail.className='muted';detail.textContent=`${item.actor} · ${new Date(item.recorded_at).toLocaleString()} · ${item.reason}`;li.append(strong,detail);root.append(li)}}
async function openTool(item){$('toolEditor').hidden=false;$('toolTitle').textContent=`${item.label} declaration`;$('toolKey').value=item.tool_key;$('toolVersion').value=item.version;$('availability').value=item.availability;$('versionText').value=item.version_text;$('accessMethod').value=item.access_method;$('toolNotes').value=item.notes;$('toolReason').value='';$('toolForm').querySelectorAll('input,select,textarea,button[type=submit]').forEach(node=>node.disabled=!state.can_edit);await history('tool',item.tool_key,$('toolHistory'));$('toolEditor').scrollIntoView({behavior:'smooth',block:'nearest'})}
async function openScope(item){$('scopeEditor').hidden=false;$('scopeTitle').textContent=`${item.scope_label} coverage`;$('scopeId').value=item.scope_id;$('scopeVersion').value=item.version;$('nmapCoverage').value=item.nmap_coverage;$('arkimeCoverage').value=item.arkime_coverage;$('kibanaCoverage').value=item.kibana_coverage;$('configCoverage').value=item.config_coverage;$('nmapAuthorization').value=item.nmap_authorization;$('deviceEvidence').value=item.device_evidence;$('scopeNotes').value=item.notes;$('scopeReason').value='';const stored=new Set(item.blind_spots.filter(value=>value!=='active_scan_prohibited'));$('blindSpots').querySelectorAll('input').forEach(input=>input.checked=stored.has(input.value));$('scopeForm').querySelectorAll('input,select,textarea,button[type=submit]').forEach(node=>node.disabled=!state.can_edit);showProhibited();await history('scope',item.scope_id,$('scopeHistory'));$('scopeEditor').scrollIntoView({behavior:'smooth',block:'nearest'})}
function showProhibited(){$('prohibitedNote').hidden=$('nmapAuthorization').value!=='prohibited'}$('nmapAuthorization').onchange=showProhibited;
async function load(){setStatus('Loading Mission Environment…');try{state=await api(`/api/mission-environment?limit=${limit}&offset=${offset}`);renderTools();renderScopes();setStatus(state.can_edit?'Mission Environment loaded. Changes require a reason.':'Mission Environment loaded read-only.')}catch(error){setStatus(error.message,true)}}
$('toolForm').onsubmit=async event=>{event.preventDefault();try{await api(`/api/mission-environment/tools/${encodeURIComponent($('toolKey').value)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({expected_version:Number($('toolVersion').value),availability:$('availability').value,version_text:$('versionText').value,access_method:$('accessMethod').value,notes:$('toolNotes').value,reason:$('toolReason').value})});$('toolEditor').hidden=true;await load();setStatus('Tool declaration saved. Relevant passive guidance will use the new version after analysts review it.')}catch(error){setStatus(error.message,true)}};
$('scopeForm').onsubmit=async event=>{event.preventDefault();try{const blind_spots=[...$('blindSpots').querySelectorAll('input:checked')].map(input=>input.value);await api(`/api/mission-environment/scopes/${encodeURIComponent($('scopeId').value)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({expected_version:Number($('scopeVersion').value),nmap_coverage:$('nmapCoverage').value,arkime_coverage:$('arkimeCoverage').value,kibana_coverage:$('kibanaCoverage').value,config_coverage:$('configCoverage').value,nmap_authorization:$('nmapAuthorization').value,device_evidence:$('deviceEvidence').value,blind_spots,notes:$('scopeNotes').value,reason:$('scopeReason').value})});$('scopeEditor').hidden=true;await load();$('scopeRows').closest('.table-wrap').scrollLeft=0;setStatus('Coverage declaration saved. Prohibited blocks later Nmap collection after exact review; Unknown does not imply permission.')}catch(error){setStatus(error.message,true)}};
$('cancelTool').onclick=()=>{$('toolEditor').hidden=true};$('cancelScope').onclick=()=>{$('scopeEditor').hidden=true;$('scopeRows').closest('.table-wrap').scrollLeft=0};$('previous').onclick=()=>{offset=Math.max(0,offset-limit);load()};$('next').onclick=()=>{if(offset+limit<state.scope_total){offset+=limit;load()}};load();
})();</script></body></html>''')
